<script>
(function(){let idx=0,wrap=document.getElementById('travelItems'),tpl=document.getElementById('travelItemTemplate');function money(n){return '$'+Number(n||0).toFixed(2)}function calc(){let sub=0;wrap.querySelectorAll('.tdc-item').forEach(r=>sub+=(parseFloat(r.querySelector('.item-qty').value)||0)*(parseFloat(r.querySelector('.item-price').value)||0));let fee=parseFloat(document.querySelector('[name=service_fee]').value)||0,disc=parseFloat(document.querySelector('[name=discount]').value)||0;document.getElementById('tdSubtotal').textContent=money(sub);document.getElementById('tdGrand').textContent=money(Math.max(0,sub+fee-disc))}function add(type,title){let f=tpl.content.cloneNode(true),row=f.querySelector('.tdc-item'),i=idx++;row.querySelector('.item-type').name=`items[${i}][item_type]`;row.querySelector('.item-title').name=`items[${i}][title]`;row.querySelector('.item-desc').name=`items[${i}][description]`;row.querySelector('.item-qty').name=`items[${i}][quantity]`;row.querySelector('.item-price').name=`items[${i}][unit_price]`;if(type)row.querySelector('.item-type').value=type;if(title)row.querySelector('.item-title').value=title;row.addEventListener('input',calc);row.querySelector('.tdc-remove').onclick=()=>{row.remove();calc()};wrap.appendChild(row);calc()}document.getElementById('addTravelItem').onclick=()=>add();document.querySelectorAll('.money-input').forEach(x=>x.addEventListener('input',calc));let initial=document.querySelector('[name=type]').value;if(initial==='hotel')add('hotel','Hotel stay');else if(initial==='car')add('car','Car rental');else if(initial==='flight')add('flight','Flight');else if(initial==='package'){add('flight','Flight');add('hotel','Hotel stay');add('transfer','Airport transfer')}else add('other','Travel service');calc()})();
</script>
